/* xx_irwinpac_extractor.c - search raw data for IRWINPAC.
 *
 * Scans for:
 *   49 72 77 69 6E 50 61 63 14 00 at +0  ("IrwinPac..")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the irwinpac reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/irwinpac/xx_irwinpac.h"

static const uint8_t k_anchor0[] = { 0x49, 0x72, 0x77, 0x69, 0x6E, 0x50, 0x61, 0x63, 0x14, 0x00 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_IRWINPAC };

static Abstractformat *xx_irwinpac_search_open(xx_io_device *window) {
    xx_irwinpac *reader = xx_irwinpac_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_irwinpac_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_irwinpac_free((xx_irwinpac *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_irwinpac_search_open, xx_irwinpac_search_close
};

static xx_format_search_state *xx_irwinpac_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_irwinpac_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_irwinpac_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_irwinpac_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_irwinpac_extractor = {
    xx_irwinpac_create_format_search,
    xx_irwinpac_get_current_format_info,
    xx_irwinpac_format_search_find_next,
    xx_irwinpac_free_format_search
};
